@file:OptIn(InternalResourceApi::class, ExperimentalResourceApi::class)

package io.github.jonnyfrick.musicbootcamp.ui

import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlin.time.Duration.Companion.milliseconds
import org.jetbrains.compose.resources.ExperimentalResourceApi
import org.jetbrains.compose.resources.InternalResourceApi
import org.jetbrains.compose.resources.ResourceReader

/**
 * Reads each resource file once and keeps it, so the texts on screen come from memory.
 *
 * In the browser, Compose reads every string anew from the browser's cache storage (a blob sliced
 * per string). In Edge on an iPad that read failed after a download ("NotReadableError: The I/O
 * read operation failed"), and since the screens load their texts while composing, the app broke.
 * The string files are small (some 10 KB per language); the piano samples are read elsewhere
 * (`Res.readBytes`) and do not pass through here.
 */
internal class MemoryResourceReader(private val source: ResourceReader) : ResourceReader {
    private val mutex = Mutex()
    private val files = mutableMapOf<String, CompletableDeferred<ByteArray>>()

    override suspend fun read(path: String): ByteArray = file(path)

    override suspend fun readPart(path: String, offset: Long, size: Long): ByteArray =
        file(path).copyOfRange(offset.toInt(), (offset + size).toInt())

    override fun getUri(path: String): String = source.getUri(path)

    private suspend fun file(path: String): ByteArray {
        var load = false
        val entry = mutex.withLock {
            files[path] ?: CompletableDeferred<ByteArray>().also { files[path] = it; load = true }
        }
        if (load) {
            runCatching { retrying(RETRIES) { source.read(path) } }
                .onSuccess { entry.complete(it) }
                .onFailure { error ->
                    // Not kept: the next text asks again.
                    mutex.withLock { files.remove(path) }
                    entry.completeExceptionally(error)
                }
        }
        return entry.await()
    }

    private companion object {
        val RETRIES = listOf(200.milliseconds, 1000.milliseconds)
    }
}
