package io.github.jonnyfrick.musicbootcamp.web

// A FloatArray is a Float32Array here: the worklet's and the worker's arrays are taken as they are.

internal actual fun microphoneBlocks(deliver: (microphone: FloatArray, reference: FloatArray) -> Unit) = setMicrophoneHook(deliver)

private fun setMicrophoneHook(deliver: (FloatArray, FloatArray) -> Unit): Unit =
    js("{ globalThis.__mbc.onMicrophone = function (mic, ref) { deliver(mic, ref); }; }")

internal actual fun modelRunWindow(id: Int, window: FloatArray, done: (error: String, notes: FloatArray?, onsets: FloatArray?) -> Unit) =
    postWindow(id, window, done)

private fun postWindow(id: Int, window: FloatArray, done: (String, FloatArray?, FloatArray?) -> Unit): Unit = js(
    """{
        var model = globalThis.__mbc.models[id];
        model.done = function (error, notes, onsets) { done(error, notes, onsets); };
        model.sent = performance.now();
        model.worker.postMessage({ type: 'run', window: window });
    }""",
)
