/**
 * The first start, on the practice screen: what the app does, then three steps — choose what you
 * play on, check that its notes arrive, start the first exercise. Gone once skipped or started.
 */
@Composable
internal fun WelcomeCard(controller: AppController) {
    val source = controller.preferences.inputSource
    Card(
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.primaryContainer),
        modifier = Modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 8.dp),
    ) {
        Column(Modifier.padding(vertical = 16.dp), verticalArrangement = Arrangement.spacedBy(4.dp)) {
            CardText(stringResource(Res.string.welcome_title), MaterialTheme.typography.titleLarge, heading = true)
            CardText(stringResource(Res.string.welcome_text))

            WelcomeStep(1, stringResource(Res.string.welcome_step_input))
            RadioSetting(
                options = InputSource.entries,
                selected = source,
                label = { inputLabel(it) },
                enabled = { it != InputSource.MICROPHONE || controller.audioUnavailableReason == null },
                onSelect = { chosen ->
                    controller.stopMicTest()
                    controller.stopMidiTest()
                    controller.setInputSource(chosen)
                },
            )
            CardText(
                when (source) {
                    InputSource.MICROPHONE -> stringResource(Res.string.welcome_microphone, instrumentName(controller.preferences.instrument))
                    InputSource.MIDI -> selectedInput(controller)?.let { stringResource(Res.string.welcome_keyboard, it) }
                        ?: stringResource(Res.string.welcome_no_keyboard)
                    InputSource.SCREEN_KEYS -> stringResource(Res.string.welcome_screen_keys)
                },
                MaterialTheme.typography.bodyMedium,
            )

            if (source != InputSource.SCREEN_KEYS) {
                WelcomeStep(2, stringResource(Res.string.welcome_step_check))
                InputCheck(controller, source)
            }

            WelcomeStep(if (source == InputSource.SCREEN_KEYS) 2 else 3, stringResource(Res.string.welcome_step_start))
            CardText(stringResource(Res.string.welcome_start_text))
            Row(
                Modifier.fillMaxWidth().padding(horizontal = 8.dp),
                horizontalArrangement = Arrangement.spacedBy(8.dp, Alignment.End),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                TextButton(onClick = controller::finishWelcome) { Text(stringResource(Res.string.welcome_skip)) }
                Button(onClick = {
                    controller.finishWelcome()
                    controller.startPractice()
                }) { Text(stringResource(Res.string.welcome_go)) }
            }
        }
    }
}

/** Step 2 of the welcome: the microphone's level and the note heard, or the keyboard's last key. */
@Composable
private fun InputCheck(controller: AppController, source: InputSource) {
    val microphone = source == InputSource.MICROPHONE
    val testing = if (microphone) controller.micTesting else controller.midiTesting
    val arrived = if (microphone) controller.micTestNote?.midiNote else controller.midiTestNotes.firstOrNull()?.data1
    Row(
        Modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 4.dp),
        horizontalArrangement = Arrangement.spacedBy(12.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        if (testing) {
            OutlinedButton(onClick = { controller.stopMicTest(); controller.stopMidiTest() }, colors = onCardColors()) { Text(stringResource(Res.string.stop_test)) }
            if (microphone) {
                val levelDescription = stringResource(Res.string.microphone_level)
                LinearProgressIndicator(
                    progress = { (controller.microphoneLevel * 5).toFloat().coerceIn(0f, 1f) },
                    modifier = Modifier.width(80.dp).semantics { contentDescription = levelDescription },
                )
            }
        } else {
            OutlinedButton(
                onClick = if (microphone) controller::startMicTest else controller::startMidiTest,
                enabled = microphone || controller.inputDevices.isNotEmpty(),
                colors = onCardColors(),
            ) { Text(stringResource(Res.string.welcome_check_button)) }
        }
    }
    if (testing) {
        Row(
            Modifier.padding(horizontal = SettingPadding).semantics(mergeDescendants = true) { liveRegion = LiveRegionMode.Polite },
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(8.dp),
        ) {
            if (arrived != null) {
                Icon(AppIcons.Check, contentDescription = null, tint = MaterialTheme.extendedColors.correct, modifier = Modifier.size(20.dp))
            }
            Text(
                when {
                    arrived != null -> stringResource(Res.string.welcome_arrived, controller.noteName(arrived))
                    microphone && controller.micTestSilent -> stringResource(Res.string.microphone_silent)
                    else -> stringResource(Res.string.play_a_key)
                },
                style = MaterialTheme.typography.titleMedium,
                color = MaterialTheme.colorScheme.onPrimaryContainer,
            )
        }
    }
}

@Composable
private fun onCardColors() = ButtonDefaults.outlinedButtonColors(contentColor = MaterialTheme.colorScheme.onPrimaryContainer)

@Composable
private fun WelcomeStep(number: Int, title: String) {
    Text(
        "$number  $title",
        style = MaterialTheme.typography.titleMedium,
        fontWeight = FontWeight.SemiBold,
        color = MaterialTheme.colorScheme.onPrimaryContainer,
        modifier = Modifier.padding(start = SettingPadding, end = SettingPadding, top = 12.dp).semantics { heading() },
    )
}

@Composable
private fun CardText(text: String, style: androidx.compose.ui.text.TextStyle = MaterialTheme.typography.bodyMedium, heading: Boolean = false) {
    Text(
        text,
        style = style,
        color = MaterialTheme.colorScheme.onPrimaryContainer,
        modifier = Modifier.fillMaxWidth().padding(horizontal = SettingPadding).let { if (heading) it.semantics { heading() } else it },
    )
}

/** A tip shown once, at the moment it matters; "Got it" puts it away for good. */
@Composable
internal fun HintCard(text: String, onDismiss: () -> Unit) {
    Card(
        colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.tertiaryContainer),
        modifier = Modifier.fillMaxWidth().padding(horizontal = SettingPadding, vertical = 8.dp),
    ) {
        Row(Modifier.padding(start = 16.dp, end = 16.dp, top = 16.dp), horizontalArrangement = Arrangement.spacedBy(12.dp)) {
            Icon(AppIcons.Info, contentDescription = null, tint = MaterialTheme.colorScheme.onTertiaryContainer, modifier = Modifier.size(20.dp))
            Text(text, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onTertiaryContainer)
        }
        TextButton(onClick = onDismiss, modifier = Modifier.align(Alignment.End).padding(end = 8.dp)) {
            Text(stringResource(Res.string.got_it))
        }
    }
}

/** Settings → Help: how the app works, the tips, and the introduction once more. */
@Composable
internal fun HelpPage(controller: AppController) {
    SettingsSection(stringResource(Res.string.help_how)) {
        SettingHint(stringResource(Res.string.help_how_play))
        SettingHint(stringResource(Res.string.help_how_memory))
        SettingHint(stringResource(Res.string.help_how_setups))
    }
    SettingsSection(stringResource(Res.string.help_tips)) {
        SettingHint(stringResource(Res.string.hint_microphone))
        SettingHint(stringResource(Res.string.help_tip_display))
        SettingHint(stringResource(Res.string.help_tip_tempo))
        if (controller.isWeb) SettingHint(stringResource(Res.string.help_tip_backup))
    }
    SettingsSection(stringResource(Res.string.help_again)) {
        SettingHint(stringResource(Res.string.help_again_hint))
        OutlinedButton(
            onClick = controller::showHintsAgain,
            enabled = !controller.running,
            modifier = Modifier.padding(horizontal = SettingPadding, vertical = 8.dp),
        ) { Text(stringResource(Res.string.help_again_button)) }
    }
}
