package io.github.jonnyfrick.musicbootcamp.core.model

import kotlinx.serialization.Serializable

/**
 * The exercises a new setup can start from. Fixed: a setup made from one changes only its own
 * copy of the settings, and "reset to template" brings these values back (its learned sequences
 * stay). The tone always sounds for half the breathing time.
 */
@Serializable
enum class SetupTemplate(
    val settings: PracticeSettings,
    /** The name of a setup made from it where the UI's translation is not at hand. */
    val defaultName: String,
) {
    /** Single notes in two octaves, steps up to a fifth, all equally often, slow. */
    BEGINNER(
        practice(
            mode = PracticeMode.MONOPHONIC,
            low = 48,
            high = 72,
            breathingTime = 4.0f,
            // Minor second … fifth (tritone included), nothing larger.
            intervals = listOf(5, 5, 5, 5, 5, 5, 5, 0, 0, 0, 0),
            learnedProbability = 0.2,
        ),
        "Beginner",
    ),

    /** Single notes in three octaves, every interval equally often. */
    ADVANCED(
        practice(
            mode = PracticeMode.MONOPHONIC,
            low = 48,
            high = 84,
            breathingTime = 2.5f,
            intervals = List(PracticeSettings.INTERVAL_COUNT) { 5 },
            learnedProbability = 0.3,
        ),
        "Advanced",
    ),

    /** The author's Java setup for single notes: five octaves, mostly large intervals, fast. */
    PRO(
        practice(
            mode = PracticeMode.MONOPHONIC,
            low = 36,
            high = 96,
            breathingTime = 1.0f,
            intervals = listOf(2, 2, 2, 2, 10, 5, 10, 10, 10, 10, 8),
            learnedProbability = 0.8,
        ),
        "Pro",
    ),

    /** The author's Java setup for two voices: two octaves, intervals up to a fifth, slow. */
    TWO_VOICES(
        practice(
            mode = PracticeMode.TWO_VOICES_PURE_RANDOM,
            low = 48,
            high = 72,
            breathingTime = 6.0f,
            intervals = listOf(2, 2, 2, 2, 2, 2, 2, 0, 0, 0, 0),
            learnedProbability = 0.8,
        ),
        "Two voices",
    ),
    ;
}

private fun practice(
    mode: PracticeMode,
    low: Int,
    high: Int,
    breathingTime: Float,
    intervals: List<Int>,
    learnedProbability: Double,
) = PracticeSettings(
    mode = mode,
    breathingTime = breathingTime,
    sustain = 50,
    midiOutVelocity = 80,
    lowLimit = low,
    highLimit = high,
    startPosition = SettingsRules.startPosition(low, high),
    intervalPriorities = intervals,
    learnedProbability = learnedProbability,
    memorySize = 5,
    // A new setup has nothing learned yet: without this, the share of learned sequences stays empty.
    learnNewSequences = true,
)
