/** The pages of the settings (Java: MusicBootCamp → Preferences, `PreferencesDialog`). */
internal enum class SettingsPage(val title: StringResource, val icon: ImageVector) {
    INPUT(Res.string.settings_input, AppIcons.Mic),
    MIDI(Res.string.settings_midi, AppIcons.Speaker),
    TUNING(Res.string.settings_tuning, AppIcons.Tune),
    APPEARANCE(Res.string.settings_appearance, AppIcons.DarkMode),
    RECOGNITION(Res.string.settings_recognition, AppIcons.GraphicEq),
    DATA(Res.string.settings_data, AppIcons.Save),
    HELP(Res.string.settings_help, AppIcons.Help),
    ABOUT(Res.string.settings_about, AppIcons.Info),
}

/**
 * Material's list-detail pattern: the pages as a list, one page at a time on phones (with the
 * system's back gesture), list and page side by side on wide windows.
 */
@OptIn(ExperimentalMaterial3AdaptiveApi::class, ExperimentalMaterial3Api::class, ExperimentalComposeUiApi::class)
@Composable
internal fun SettingsScreen(controller: AppController, snackbar: SnackbarHostState) {
    val navigator = rememberListDetailPaneScaffoldNavigator<SettingsPage>()
    val scope = rememberCoroutineScope()
    val twoPanes = navigator.scaffoldValue[ListDetailPaneScaffoldRole.List] != PaneAdaptedValue.Hidden &&
        navigator.scaffoldValue[ListDetailPaneScaffoldRole.Detail] != PaneAdaptedValue.Hidden
    // The recognition's tuning tools are for debug builds only.
    val pages = SettingsPage.entries.filter {
        (it != SettingsPage.RECOGNITION || controller.debugTools) && (it != SettingsPage.DATA || controller.canExchangeSetups)
    }
    // Side by side, a page is always shown: the first one until another is chosen.
    val page = navigator.currentDestination?.contentKey ?: SettingsPage.INPUT

    // The system's back (gesture, button, Escape) returns from a page to the list where only one shows.
    BackHandler(enabled = navigator.canNavigateBack()) { scope.launch { navigator.navigateBack() } }

    ListDetailPaneScaffold(
        directive = navigator.scaffoldDirective,
        scaffoldState = navigator.scaffoldState,
        listPane = {
            AnimatedPane {
                Scaffold(
                    topBar = { TopAppBar(title = { Text(stringResource(Res.string.nav_settings)) }) },
                    snackbarHost = { if (!twoPanes) SnackbarHost(snackbar) },
                ) { padding ->
                    CenteredColumn(Modifier.padding(padding)) {
                        pages.forEach { entry ->
                            NavigationSetting(
                                title = stringResource(entry.title),
                                summary = summary(controller, entry),
                                icon = entry.icon,
                                selected = twoPanes && entry == page,
                                onClick = { scope.launch { navigator.navigateTo(ListDetailPaneScaffoldRole.Detail, entry) } },
                            )
                        }
                    }
                }
            }
        },
        detailPane = {
            AnimatedPane {
                Scaffold(
                    topBar = {
                        TopAppBar(
                            title = { Text(stringResource(page.title)) },
                            navigationIcon = {
                                if (!twoPanes) {
                                    IconButton(onClick = { scope.launch { navigator.navigateBack() } }) {
                                        Icon(AppIcons.ArrowBack, contentDescription = stringResource(Res.string.back))
                                    }
                                }
                            },
                        )
                    },
                    snackbarHost = { SnackbarHost(snackbar) },
                ) { padding ->
                    CenteredColumn(Modifier.padding(padding)) {
                        when (page) {
                            SettingsPage.INPUT -> InputSettings(controller)
                            SettingsPage.MIDI -> MidiSettings(controller)
                            SettingsPage.TUNING -> TuningSettings(controller)
                            SettingsPage.APPEARANCE -> AppearanceSettings(controller)
                            SettingsPage.RECOGNITION -> RecognitionSettings(controller)
                            SettingsPage.DATA -> DataPage(controller)
                            SettingsPage.HELP -> HelpPage(controller)
                            SettingsPage.ABOUT -> AboutPage(controller)
                        }
                    }
                }
            }
        },
    )
}

/** What a page is set to, in one line of the list. */
@Composable
private fun summary(controller: AppController, page: SettingsPage): String? {
    val preferences = controller.preferences
    return when (page) {
        SettingsPage.INPUT ->
            if (preferences.inputSource == InputSource.MICROPHONE) "${stringResource(Res.string.microphone)} · ${instrumentName(preferences.instrument)}"
            else inputLabel(preferences.inputSource)
        SettingsPage.MIDI -> listOfNotNull(selectedInput(controller), selectedOutput(controller)).joinToString(" → ").ifEmpty { null }
        SettingsPage.TUNING -> "A = ${stringResource(Res.string.value_hz, preferences.referenceAHz.toString())}"
        SettingsPage.APPEARANCE -> themeLabel(preferences.theme)
        SettingsPage.RECOGNITION -> stringResource(Res.string.settings_recognition_summary)
        SettingsPage.DATA -> stringResource(Res.string.settings_data_summary)
        SettingsPage.HELP -> stringResource(Res.string.settings_help_summary)
        SettingsPage.ABOUT -> stringResource(Res.string.settings_about_summary)
    }
}

@Composable
private fun themeLabel(theme: ThemeMode) = stringResource(
    when (theme) {
        ThemeMode.SYSTEM -> Res.string.theme_system
        ThemeMode.LIGHT -> Res.string.theme_light
        ThemeMode.DARK -> Res.string.theme_dark
    },
)

@Composable
private fun AppearanceSettings(controller: AppController) {
    SettingsSection(stringResource(Res.string.theme)) {
        RadioSetting(
            options = ThemeMode.entries,
            selected = controller.preferences.theme,
            label = { themeLabel(it) },
            onSelect = controller::setTheme,
        )
    }
}

@Composable
internal fun inputLabel(source: InputSource) = stringResource(
    when (source) {
        InputSource.MIDI -> Res.string.input_midi
        InputSource.MICROPHONE -> Res.string.input_microphone
        InputSource.SCREEN_KEYS -> Res.string.input_screen_keys
    },
)

internal fun selectedInput(controller: AppController): String? =
    controller.preferences.midiInputDevice?.takeIf { it in controller.inputDevices } ?: controller.defaultDevice(controller.inputDevices)

private fun selectedOutput(controller: AppController): String? =
    controller.preferences.midiOutputDevice?.takeIf { it in controller.outputDevices } ?: controller.defaultDevice(controller.outputDevices)

@Composable
private fun InputSettings(controller: AppController) {
    val preferences = controller.preferences
    val running = controller.running

    SettingsSection(stringResource(Res.string.input_source)) {
        RadioSetting(
            options = InputSource.entries,
            selected = preferences.inputSource,
            label = { inputLabel(it) },
            enabled = { !running && (it != InputSource.MICROPHONE || controller.audioUnavailableReason == null) },
            onSelect = controller::setInputSource,
        )
        controller.audioUnavailableReason?.let { SettingHint(it) }
    }
    if (preferences.inputSource != InputSource.MICROPHONE) return

    SettingsSection(stringResource(Res.string.microphone)) {
        val systemDefault = stringResource(Res.string.system_default)
        val instrumentNames = PlayerInstrument.entries.associateWith { instrumentName(it) }
        ChoiceSetting(
            title = stringResource(Res.string.microphone),
            options = listOf<String?>(null) + controller.audioInputDevices,
            selected = preferences.audioInputDevice?.takeIf { it in controller.audioInputDevices },
            label = { it ?: systemDefault },
            onSelect = controller::selectAudioInputDevice,
            onOpen = controller::refreshDevices,
            enabled = !running,
            icon = AppIcons.Mic,
        )
        if (controller.microphoneNamesHidden) SettingHint(stringResource(Res.string.microphone_names_hidden))
        ChoiceSetting(
            title = stringResource(Res.string.instrument),
            options = PlayerInstrument.entries,
            selected = preferences.instrument,
            label = { instrumentNames.getValue(it) },
            onSelect = controller::setInstrument,
            enabled = !running,
            icon = AppIcons.MusicNote,
        )
        SettingHint(stringResource(Res.string.instrument_hint))
        if (controller.noteModelTooSlow) SettingHint(stringResource(Res.string.model_recognition_too_slow))
        if (preferences.instrument.transposition != 0) {
            SwitchSetting(
                title = stringResource(Res.string.show_transposed),
                checked = preferences.showTransposed,
                onCheckedChange = controller::setShowTransposed,
                supporting = stringResource(Res.string.show_transposed_hint),
            )
        }
        SwitchSetting(
            title = stringResource(Res.string.headphones),
            checked = preferences.usesHeadphones,
            onCheckedChange = controller::setUsesHeadphones,
            enabled = !running,
            supporting = when {
                preferences.usesHeadphones -> stringResource(Res.string.headphones_on_hint)
                controller.ownSynthName != null -> stringResource(Res.string.headphones_off_hint, controller.ownSynthName!!)
                else -> stringResource(Res.string.headphones_off_hint_plain)
            },
        )
        SwitchSetting(
            title = stringResource(Res.string.octaves),
            checked = preferences.octavesCountAsCorrect,
            onCheckedChange = controller::setOctavesCountAsCorrect,
            enabled = !running,
            supporting = stringResource(Res.string.octaves_hint),
        )
        MicrophoneTest(controller)
    }
}

@Composable
internal fun instrumentName(instrument: PlayerInstrument): String = stringResource(
    when (instrument) {
        PlayerInstrument.PIANO -> Res.string.instrument_piano
        PlayerInstrument.FLUTE -> Res.string.instrument_flute
        PlayerInstrument.OBOE -> Res.string.instrument_oboe
        PlayerInstrument.CLARINET_B_FLAT -> Res.string.instrument_clarinet
        PlayerInstrument.ALTO_SAXOPHONE -> Res.string.instrument_alto_saxophone
        PlayerInstrument.TENOR_SAXOPHONE -> Res.string.instrument_tenor_saxophone
        PlayerInstrument.TRUMPET_B_FLAT -> Res.string.instrument_trumpet
        PlayerInstrument.HORN_F -> Res.string.instrument_horn
        PlayerInstrument.TROMBONE -> Res.string.instrument_trombone
        PlayerInstrument.OTHER_SUSTAINED -> Res.string.instrument_other
    },
)

@Composable
private fun MicrophoneTest(controller: AppController) {
    ButtonRow {
        if (controller.micTesting) {
            OutlinedButton(onClick = controller::stopMicTest) { Text(stringResource(Res.string.stop_test)) }
            val levelDescription = stringResource(Res.string.microphone_level)
            LinearProgressIndicator(
                progress = { (controller.microphoneLevel * 5).toFloat().coerceIn(0f, 1f) },
                modifier = Modifier.width(120.dp).semantics { contentDescription = levelDescription },
            )
            val note = controller.micTestNote
            Text(
                if (controller.micTestSilent) {
                    stringResource(Res.string.microphone_silent)
                } else if (note == null) {
                    stringResource(Res.string.play_a_key)
                } else {
                    val cents = note.cents.roundToInt()
                    "${controller.noteName(note.midiNote)} (${if (cents >= 0) "+" else ""}$cents ct)"
                },
                style = MaterialTheme.typography.titleMedium,
                modifier = Modifier.semantics { liveRegion = LiveRegionMode.Polite },
            )
        } else {
            OutlinedButton(onClick = controller::startMicTest, enabled = !controller.running) {
                Text(stringResource(Res.string.test_microphone))
            }
        }
    }
    SettingHint(stringResource(Res.string.test_microphone_hint))
}

@Composable
private fun MidiSettings(controller: AppController) {
    val running = controller.running
    val noDevice = stringResource(Res.string.no_device)
    SettingsSection(null) {
        controller.midiUnavailableReason?.let { SettingHint(it, color = MaterialTheme.colorScheme.error) }
        ChoiceSetting(
            title = stringResource(Res.string.midi_in),
            options = controller.inputDevices,
            selected = selectedInput(controller),
            label = { it ?: noDevice },
            onSelect = { it?.let(controller::selectInputDevice) },
            onOpen = controller::refreshDevices,
            enabled = !running,
            icon = AppIcons.MusicNote,
        )
        ChoiceSetting(
            title = stringResource(Res.string.midi_out),
            options = controller.outputDevices,
            selected = selectedOutput(controller),
            label = { it ?: noDevice },
            onSelect = { it?.let(controller::selectOutputDevice) },
            onOpen = controller::refreshDevices,
            enabled = !running,
            icon = AppIcons.Speaker,
        )
        if (controller.canConnectBluetoothMidi) {
            ButtonRow {
                OutlinedButton(onClick = controller::connectBluetoothMidi, enabled = !running) {
                    Text(stringResource(Res.string.bluetooth_midi))
                }
            }
        }
        SettingHint(stringResource(Res.string.devices_hint))
        controller.ownSynthName?.let { SettingHint(stringResource(Res.string.own_synth_hint, it)) }
        if (controller.pianoSampled && BUILT_IN_PIANO in controller.outputDevices) SettingHint(stringResource(Res.string.piano_credits, BUILT_IN_PIANO))
    }
    SettingsSection(stringResource(Res.string.test_midi)) {
        ButtonRow {
            if (controller.midiTesting) {
                OutlinedButton(onClick = controller::stopMidiTest) { Text(stringResource(Res.string.stop_test)) }
            } else {
                OutlinedButton(onClick = controller::startMidiTest, enabled = !running && controller.inputDevices.isNotEmpty()) {
                    Text(stringResource(Res.string.test_midi))
                }
            }
            OutlinedButton(onClick = controller::playTestNote, enabled = !running && controller.outputDevices.isNotEmpty()) {
                Text(stringResource(Res.string.play_test_note))
            }
        }
        if (controller.midiTesting) {
            val notes = controller.midiTestNotes
            Column(Modifier.padding(horizontal = SettingPadding).semantics { liveRegion = LiveRegionMode.Polite }) {
                Text(
                    notes.firstOrNull()?.let { latest ->
                        stringResource(Res.string.midi_test_note, NoteNames.displayName(latest.data1), latest.data1, latest.data2)
                    } ?: stringResource(Res.string.play_a_key),
                    style = MaterialTheme.typography.titleMedium,
                )
                if (notes.size > 1) {
                    Text(
                        stringResource(Res.string.midi_test_before, notes.drop(1).joinToString("  ") { NoteNames.displayName(it.data1) }),
                        style = MaterialTheme.typography.bodyMedium,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
        }
        SettingHint(stringResource(Res.string.midi_test_hint))
    }
}

@Composable
private fun TuningSettings(controller: AppController) {
    val reference = controller.preferences.referenceAHz
    SettingsSection(null) {
        SliderSetting(
            title = stringResource(Res.string.reference_a),
            value = reference,
            range = Tuning.MIN_A_HZ..Tuning.MAX_A_HZ,
            step = Tuning.STEP_HZ,
            valueText = stringResource(Res.string.value_hz, reference.toString()),
            onChange = controller::setReferenceA,
            supporting = stringResource(Res.string.tuning_hint),
            fineSteps = true,
        )
        ButtonRow {
            TextButton(onClick = { controller.setReferenceA(Tuning.STANDARD_A_HZ) }, enabled = reference != Tuning.STANDARD_A_HZ) {
                Text(stringResource(Res.string.reset_440))
            }
        }
    }
}

/** Backing up the setups to a file and bringing them back, on this device or another. */
@Composable
private fun DataPage(controller: AppController) {
    SettingsSection(stringResource(Res.string.data_where)) {
        SettingHint(stringResource(if (controller.isWeb) Res.string.data_where_web else Res.string.data_where_device))
        when (controller.storageKept) {
            true -> SettingHint(stringResource(Res.string.data_storage_kept))
            false -> SettingHint(stringResource(Res.string.data_storage_not_kept))
            null -> Unit
        }
    }
    SettingsSection(stringResource(Res.string.data_backup)) {
        SettingHint(lastBackupText(controller.preferences.lastBackupAt), color = MaterialTheme.colorScheme.onSurface)
        SettingHint(stringResource(Res.string.data_backup_hint, controller.setupNames.size))
        Button(
            onClick = controller::exportAllSetups,
            enabled = !controller.running,
            modifier = Modifier.padding(horizontal = SettingPadding, vertical = 8.dp),
        ) { Text(stringResource(Res.string.data_backup_button)) }
        if (controller.isWeb) {
            SwitchSetting(
                title = stringResource(Res.string.backup_reminder_setting),
                checked = controller.preferences.backupReminder,
                onCheckedChange = controller::setBackupReminder,
                supporting = stringResource(Res.string.backup_reminder_setting_hint),
            )
        }
    }
    SettingsSection(stringResource(Res.string.data_restore)) {
        SettingHint(stringResource(Res.string.data_restore_hint))
        OutlinedButton(
            onClick = controller::importSetup,
            enabled = !controller.running,
            modifier = Modifier.padding(horizontal = SettingPadding, vertical = 8.dp),
        ) { Text(stringResource(Res.string.data_restore_button)) }
    }
    var confirmReset by remember { mutableStateOf(false) }
    SettingsSection(stringResource(Res.string.app_reset)) {
        SettingHint(stringResource(Res.string.app_reset_hint))
        OutlinedButton(
            onClick = { confirmReset = true },
            enabled = !controller.running,
            modifier = Modifier.padding(horizontal = SettingPadding, vertical = 8.dp),
        ) { Text(stringResource(Res.string.app_reset_button), color = MaterialTheme.colorScheme.error) }
    }
    if (confirmReset) {
        ConfirmDialog(
            title = stringResource(Res.string.app_reset_title),
            text = stringResource(Res.string.app_reset_text),
            confirm = stringResource(Res.string.app_reset_confirm),
            destructive = true,
            onDismiss = { confirmReset = false },
            onConfirm = controller::resetApp,
        )
    }
}

/** "Last backup: 3 days ago", or that there is none. */
@Composable
private fun lastBackupText(lastBackupAt: Long?): String {
    if (lastBackupAt == null) return stringResource(Res.string.data_never_backed_up)
    val days = AppController.daysBetween(lastBackupAt, Clock.System.now().toEpochMilliseconds())
    val ago = when (days) {
        0 -> stringResource(Res.string.today)
        1 -> stringResource(Res.string.yesterday)
        else -> stringResource(Res.string.days_ago, days)
    }
    return stringResource(Res.string.data_last_backup, ago)
}

/** What the app keeps and sends (nothing), and who publishes it (Austrian law: § 5 ECG, § 25 MedienG). */
@Composable
private fun AboutPage(controller: AppController) {
    SettingsSection(stringResource(Res.string.privacy)) {
        SettingHint(stringResource(Res.string.privacy_local))
        if (controller.isWeb) SettingHint(stringResource(Res.string.privacy_web))
        SettingHint(stringResource(Res.string.privacy_microphone))
        SettingHint(stringResource(Res.string.privacy_backup))
    }
    SettingsSection(stringResource(Res.string.imprint)) {
        SettingHint(stringResource(Res.string.imprint_text, PUBLISHER_NAME, PUBLISHER_PLACE))
        val uriHandler = LocalUriHandler.current
        TextButton(onClick = { runCatching { uriHandler.openUri("mailto:$PUBLISHER_EMAIL") } }, modifier = Modifier.padding(horizontal = 8.dp)) {
            Text(PUBLISHER_EMAIL)
        }
        SettingHint(stringResource(Res.string.imprint_purpose))
    }
}

private const val PUBLISHER_NAME = "Jonathan Frick"
private const val PUBLISHER_PLACE = "Dornbirn"
private const val PUBLISHER_EMAIL = "jonathan.frick@gmx.at"
