package io.github.jonnyfrick.musicbootcamp.core.persistence

import io.github.jonnyfrick.musicbootcamp.core.model.SettingsRules
import io.github.jonnyfrick.musicbootcamp.core.pitch.DetectionParameters
import io.github.jonnyfrick.musicbootcamp.core.pitch.LearnedTemplates
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject

/** Minimal text-file storage the platforms provide (a directory on desktop). */
interface DocumentStore {
    suspend fun read(name: String): String?
    suspend fun write(name: String, content: String)
    suspend fun delete(name: String)
    suspend fun list(): List<String>
}

/** Keeps everything in memory — for platforms without persistent storage yet, and for tests. */
class InMemoryDocumentStore : DocumentStore {
    private val documents = mutableMapOf<String, String>()
    override suspend fun read(name: String): String? = documents[name]
    override suspend fun write(name: String, content: String) {
        documents[name] = content
    }

    override suspend fun delete(name: String) {
        documents.remove(name)
    }

    override suspend fun list(): List<String> = documents.keys.sorted()
}

/**
 * Stores setups as `setup-<name>.json` and the preferences as `preferences.json`,
 * all as JSON with a `version` field for future format changes.
 */
class SetupRepository(private val store: DocumentStore) {

    suspend fun setupNames(): List<String> =
        store.list()
            .filter { it.startsWith(SETUP_PREFIX) && it.endsWith(SUFFIX) }
            .map { it.removePrefix(SETUP_PREFIX).removeSuffix(SUFFIX) }
            .sortedBy { it.lowercase() }

    /** Loads the setup called [name]; null when it does not exist. */
    suspend fun load(name: String): Setup? {
        val text = store.read(fileName(name)) ?: return null
        return decode(text)
    }

    private suspend fun decode(text: String): Setup {
        val document = json.decodeFromString(SetupDocument.serializer(), text)
        val setup = Setup.fromDocument(document)
        // Format 1 had one late-answer tolerance for all setups, in the preferences: each setup
        // takes it over the first time it is loaded (and is saved in the current format from then on).
        if (document.version < 2) {
            setup.settings = setup.settings.copy(lateAnswerToleranceMillis = loadPreferences().lateAnswerToleranceMillis)
        }
        // Format 3 added the template a setup was made from; older setups have none, which the
        // missing field already says.
        return setup
    }

    suspend fun save(setup: Setup) {
        require(setup.name == sanitizeName(setup.name)) { "Setup name '${setup.name}' is not a valid file name" }
        store.write(fileName(setup.name), export(setup))
    }

    /** [setup] as a file to keep or take to another device: the same JSON as stored. */
    fun export(setup: Setup): String = json.encodeToString(SetupDocument.serializer(), setup.toDocument())

    /** [setups] in one file, as a backup or to move them all to another device; [importAll] reads it. */
    fun exportAll(setups: List<Setup>): String =
        json.encodeToString(SetupBackup.serializer(), SetupBackup(setups = setups.map { it.toDocument() }))

    /**
     * Reads a file made by [exportAll] or [export]: the setups in it, each checked as by [import].
     * Throws [IllegalArgumentException] with the reason if one of them is not usable.
     */
    suspend fun importAll(text: String): List<Setup> {
        val root = runCatching { json.parseToJsonElement(text).jsonObject }
            .getOrElse { throw IllegalArgumentException("Not a MusicBootCamp setup file.", it) }
        val setups = root["setups"] ?: return listOf(import(text))
        val backup = runCatching { json.decodeFromJsonElement(SetupBackup.serializer(), root) }
            .getOrElse { throw IllegalArgumentException("Not a MusicBootCamp backup file.", it) }
        require(backup.backupVersion <= BACKUP_FORMAT_VERSION) { "The backup was made by a newer version of MusicBootCamp." }
        return setups.jsonArray.map { import(it.toString()) }
    }

    /**
     * Reads a file made by [export] (on any device, by this or an older version of the app);
     * throws [IllegalArgumentException] with the reason if it is not a setup this version can use.
     * The setup keeps the name it had; the caller makes it unique.
     */
    suspend fun import(text: String): Setup {
        val document = runCatching { json.decodeFromString(SetupDocument.serializer(), text) }
            .getOrElse { throw IllegalArgumentException("Not a MusicBootCamp setup file.", it) }
        require(document.version <= SETUP_FORMAT_VERSION) { "The setup file was made by a newer version of MusicBootCamp." }
        val setup = decode(text)
        val settings = setup.settings
        val problem = when {
            settings.lowLimit < SettingsRules.LOWEST_NOTE || settings.highLimit > SettingsRules.HIGHEST_NOTE ||
                settings.highLimit - settings.lowLimit < SettingsRules.MIN_RANGE -> "range"
            settings.breathingTime !in SettingsRules.MIN_BREATHING_TIME..SettingsRules.MAX_BREATHING_TIME -> "breathing time"
            SettingsRules.intervalsProblem(settings.intervalPriorities) != null -> "intervals"
            else -> null
        }
        require(problem == null) { "The setup file has invalid settings ($problem)." }
        return setup.copy(sanitizeName(setup.name))
    }

    suspend fun delete(name: String) = store.delete(fileName(name))

    suspend fun loadPreferences(): AppPreferences {
        val stored = store.read(PREFERENCES)?.let { runCatching { json.decodeFromString(AppPreferences.serializer(), it) }.getOrNull() }
            ?: AppPreferences()
        // Detection parameters tuned against older defaults start over from the current ones
        // (and the recognition switches: from revision 7 on, the learned model by default).
        val detection = if (stored.detectionParametersRevision >= DETECTION_PARAMETERS_REVISION) stored
        else stored.copy(
            detectionParameters = DetectionParameters(),
            chordDetectionParameters = emptyMap(),
            modelRecognition = AppPreferences().modelRecognition,
            detectionParametersRevision = DETECTION_PARAMETERS_REVISION,
        )
        // "As the system" stored while that was the default becomes the new default, dark; a theme
        // chosen on purpose stays.
        val themed = if (detection.themeRevision >= THEME_REVISION) detection
        else detection.copy(
            theme = if (detection.theme == ThemeMode.SYSTEM) AppPreferences().theme else detection.theme,
            themeRevision = THEME_REVISION,
        )
        return if (themed.showGivenNotes) themed.copy(showGivenNotes = false, givenNotes = GivenNotes.NAMES) else themed
    }

    /** The player's piano, as measured by calibration (chord recognition); empty if never done. */
    suspend fun loadTemplates(): LearnedTemplates =
        store.read(TEMPLATES)?.let { runCatching { json.decodeFromString(LearnedTemplates.serializer(), it) }.getOrNull() }
            ?: LearnedTemplates()

    suspend fun saveTemplates(templates: LearnedTemplates) {
        store.write(TEMPLATES, json.encodeToString(LearnedTemplates.serializer(), templates))
    }

    suspend fun savePreferences(preferences: AppPreferences) {
        store.write(PREFERENCES, json.encodeToString(AppPreferences.serializer(), preferences))
    }

    companion object {
        private const val SETUP_PREFIX = "setup-"
        private const val SUFFIX = ".json"
        private const val PREFERENCES = "preferences.json"
        private const val TEMPLATES = "piano-templates.json"
        private const val BACKUP_FORMAT_VERSION = 1

        internal val json = Json {
            ignoreUnknownKeys = true
            encodeDefaults = true
        }

        /** Makes [name] usable as a file name: unsafe characters become `_`. */
        fun sanitizeName(name: String): String =
            name.trim().map { if (it.isLetterOrDigit() || it in "-_ ()") it else '_' }.joinToString("").ifEmpty { "setup" }

        private fun fileName(setupName: String): String = SETUP_PREFIX + sanitizeName(setupName) + SUFFIX
    }
}
